-- =============================================
-- TABLA: alumnos
-- =============================================
CREATE TABLE alumnos (
    Numero_control_alumno VARCHAR(20) PRIMARY KEY,
    Nombre                VARCHAR(100),
    carrera               VARCHAR(100),
    correo                VARCHAR(100),
    semestre              INT,
    grupo                 VARCHAR(20)
);

-- =============================================
-- TABLA: usuarios
-- =============================================
CREATE TABLE usuarios (
    usuario    VARCHAR(50) PRIMARY KEY,
    contrasena VARCHAR(100)
);

-- =============================================
-- TABLA: profesores
-- =============================================
CREATE TABLE profesores (
    id_profesor      INT PRIMARY KEY,
    ced_profesional  BIGINT,
    nombre           VARCHAR(100),
    telefono         VARCHAR(20),
    correo           VARCHAR(100),
    sexo             VARCHAR(20)
);

